     JOIN vendors v ON ((v.id = c.vendor_id)))
  WHERE ((c.id = vendor_storefront_collection_items.collection_id) AND (v.owner_user_id = ( SELECT auth.uid() AS uid))))) OR has_role('admin'::text))) with check (((EXISTS ( SELECT 1
   FROM (vendor_storefront_collections c
     JOIN vendors v ON ((v.id = c.vendor_id)))
  WHERE ((c.id = vendor_storefront_collection_items.collection_id) AND (v.owner_user_id = ( SELECT auth.uid() AS uid))))) OR has_role('admin'::text)));
drop policy if exists vendor_storefront_collections_owner_all on public.vendor_storefront_collections;
create policy vendor_storefront_collections_owner_all on public.vendor_storefront_collections as PERMISSIVE for ALL to authenticated using (((EXISTS ( SELECT 1
   FROM vendors v
  WHERE ((v.id = vendor_storefront_collections.vendor_id) AND (v.owner_user_id = ( SELECT auth.uid() AS uid))))) OR has_role('admin'::text))) with check (((EXISTS ( SELECT 1
   FROM vendors v
  WHERE ((v.id = vendor_storefront_collections.vendor_id) AND (v.owner_user_id = ( SELECT auth.uid() AS uid))))) OR has_role('admin'::text)));
drop policy if exists vendors_admin_all on public.vendors;
